For the common I²C variant, connect the SSD1306 to the ESP32 as follows:

- **VCC** → 3.3V  
- **GND** → GND  
- **SDA** → GPIO 21 (default I²C SDA)  
- **SCL** → GPIO 22 (default I²C SCL)  
- **RES** (Reset) → any available GPIO if your module exposes this pin; otherwise it can often be left unconnected

Install both the **Adafruit_SSD1306** and **Adafruit_GFX** libraries, then initialize it like this:

```cpp
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1      // Set to the GPIO wired to RES if your module has one; otherwise use -1
#define I2C_ADDRESS   0x3C    // Most common address; try 0x3D if the display does not respond

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void setup() {
  // Optional for ESP32: use different pins with Wire.setPins(SDA_PIN, SCL_PIN) before display.begin()

  if(!display.begin(SSD1306_SWITCHCAPVCC, I2C_ADDRESS)) {
    for(;;); // Halt if the display isn't found
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.println(F("Hello, ESP32!"));
  display.display();
}
```

